async function canvas(blank=false,page=pageIndex,book=M.snapshot(p)){
 const draft=M.pageView(book,page);if(blank)draft.panels=draft.panels.map(()=>M.blankPanel());const rendered=A.page(draft),svg=await window.ComicAssets.inline(rendered.svg),image=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));
 try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Comic image could not render.'));image.src=url;});const result=document.createElement('canvas');result.width=rendered.width;result.height=rendered.height;const ctx=result.getContext('2d');if(!ctx)throw new Error('Image export is unavailable.');ctx.drawImage(image,0,0);return result;}finally{URL.revokeObjectURL(url);}
}
const pngBlob=image=>new Promise((resolve,reject)=>image.toBlob(blob=>blob?resolve(blob):reject(new Error('Image export failed.')),'image/png'));
async function exportFile(pdf,blank=false,allImages=false){history();const book=M.snapshot(p),active=pageIndex,base=filename(),buttons=[$('export-png'),$('export-pdf'),$('export-blank'),$('export-all-png')];buttons.forEach(b=>b.disabled=true);say('Preparing comic download…');
 try{
  if(pdf){let doc;for(let i=0;i<book.pages.length;i++){say('Rendering PDF page '+(i+1)+' of '+book.pages.length+'…');const image=await canvas(blank,i,book),orientation=image.width>image.height?'landscape':'portrait';if(!doc)doc=new window.jspdf.jsPDF({orientation,unit:'pt',format:'letter',compress:true});else doc.addPage('letter',orientation);const w=doc.internal.pageSize.getWidth(),h=doc.internal.pageSize.getHeight(),scale=Math.min((w-48)/image.width,(h-48)/image.height);doc.addImage(image.toDataURL('image/png'),'PNG',(w-image.width*scale)/2,(h-image.height*scale)/2,image.width*scale,image.height*scale,undefined,'FAST');image.width=image.height=1;}doc.save(base+(blank?'-blank-layout':'')+'.pdf');
  }else if(allImages){const files=[];for(let i=0;i<book.pages.length;i++){say('Rendering image '+(i+1)+' of '+book.pages.length+'…');const image=await canvas(false,i,book);files.push({name:'page-'+String(i+1).padStart(2,'0')+'.png',blob:await pngBlob(image)});image.width=image.height=1;}download(await window.ComicPngBundle.zip(files),base+'-pages.zip');
  }else download(await pngBlob(await canvas(false,active,book)),base+'-page-'+String(active+1).padStart(2,'0')+'.png');
  say(pdf?'Comic PDF downloaded with all '+book.pages.length+' pages.':allImages?'All comic pages downloaded as a PNG ZIP bundle.':'Page PNG downloaded.');
 }catch(e){say('Could not export comic: '+e.message);}finally{buttons.forEach(b=>b.disabled=false);}
}
