// Object sizing and color controls keep changes in the existing undo/history flow.
for(const [id,dimension] of [['object-width','width'],['object-height','height']])$(id).addEventListener('change',()=>{const o=object(),value=Number($(id).value);if(o&&Number.isFinite(value)&&value>0)change(()=>{if(isText(o)){const box=textBox(o);box[dimension]=Math.max(dimension==='width'?80:50,Math.min(dimension==='width'?560:340,value/o.scale));}else if(o.type==='image')o[dimension==='width'?'imageWidth':'imageHeight']=Math.max(1,Math.min(dimension==='width'?600:360,value/o.scale));else o.scale=Math.max(.15,Math.min(4,value/A.dimensions(o)[dimension]));});});
